-- Run this whole file once in the Supabase SQL Editor.
create extension if not exists "pgcrypto";
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, name text not null default '', email text not null default '', phone text, vehicle_number text, vehicle_type text check (vehicle_type in ('bike','car')), role text not null default 'student' check (role in ('student','security','admin')), created_at timestamptz not null default now());
create table public.parking_slots (id uuid primary key default gen_random_uuid(), slot_number text unique not null, vehicle_type text not null check (vehicle_type in ('bike','car')), status text not null default 'available' check (status in ('available','occupied')), created_at timestamptz not null default now());
create table public.parking_sessions (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, slot_id uuid not null references public.parking_slots(id) on delete restrict, vehicle_number text not null, qr_token text unique not null, status text not null default 'pending' check (status in ('pending','active','completed','cancelled')), entry_time timestamptz, exit_time timestamptz, created_at timestamptz not null default now());
create table public.qr_codes (id uuid primary key default gen_random_uuid(), session_id uuid not null references public.parking_sessions(id) on delete cascade, qr_token text unique not null, created_at timestamptz not null default now());
create unique index one_open_session_per_student on public.parking_sessions(user_id) where status in ('pending','active');
create unique index one_reserved_slot on public.parking_sessions(slot_id) where status in ('pending','active');
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles (id,name,email,phone,vehicle_number,vehicle_type,role) values (new.id,coalesce(new.raw_user_meta_data->>'name',''),coalesce(new.email,''),new.raw_user_meta_data->>'phone',new.raw_user_meta_data->>'vehicle_number',new.raw_user_meta_data->>'vehicle_type','student'); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.is_staff() returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role in ('security','admin')) $$;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin') $$;
alter table public.profiles enable row level security; alter table public.parking_slots enable row level security; alter table public.parking_sessions enable row level security; alter table public.qr_codes enable row level security;
create policy "profile self or staff read" on public.profiles for select using (id=auth.uid() or public.is_staff());
create policy "profile self update" on public.profiles for update using (id=auth.uid()) with check (id=auth.uid() and role='student');
create policy "slots authenticated read" on public.parking_slots for select to authenticated using (true);
create policy "admin slot insert" on public.parking_slots for insert to authenticated with check (public.is_admin());
create policy "admin slot delete" on public.parking_slots for delete to authenticated using (public.is_admin());
create policy "own or staff session read" on public.parking_sessions for select using (user_id=auth.uid() or public.is_staff());
create policy "own or staff qr read" on public.qr_codes for select using (exists(select 1 from public.parking_sessions s where s.id=session_id and (s.user_id=auth.uid() or public.is_staff())));
create or replace function public.create_parking_session(p_slot_id uuid,p_token text) returns public.parking_sessions language plpgsql security definer set search_path=public as $$ declare p public.profiles; s public.parking_slots; result public.parking_sessions; begin select * into p from public.profiles where id=auth.uid(); if not found or p.role<>'student' then raise exception 'Access denied'; end if; if p.vehicle_number is null or p.vehicle_type is null then raise exception 'Vehicle details are required'; end if; if exists(select 1 from public.parking_sessions where user_id=auth.uid() and status in ('pending','active')) then raise exception 'You already have an active parking session'; end if; select * into s from public.parking_slots where id=p_slot_id for update; if not found or s.status<>'available' or s.vehicle_type<>p.vehicle_type then raise exception 'Parking slot is no longer available'; end if; insert into public.parking_sessions(user_id,slot_id,vehicle_number,qr_token,status) values(auth.uid(),p_slot_id,p.vehicle_number,p_token,'pending') returning * into result; insert into public.qr_codes(session_id,qr_token) values(result.id,p_token); return result; end; $$;
create or replace function public.approve_parking_entry(p_session_id uuid) returns public.parking_sessions language plpgsql security definer set search_path=public as $$ declare result public.parking_sessions; begin if not public.is_staff() then raise exception 'Access denied'; end if; select * into result from public.parking_sessions where id=p_session_id for update; if not found then raise exception 'Session not found'; end if; if result.status<>'pending' then raise exception 'This QR code cannot be approved'; end if; update public.parking_slots set status='occupied' where id=result.slot_id and status='available'; if not found then raise exception 'Parking slot is no longer available'; end if; update public.parking_sessions set status='active',entry_time=now() where id=p_session_id returning * into result; return result; end; $$;
create or replace function public.complete_parking_exit(p_session_id uuid) returns public.parking_sessions language plpgsql security definer set search_path=public as $$ declare result public.parking_sessions; begin if not public.is_staff() then raise exception 'Access denied'; end if; select * into result from public.parking_sessions where id=p_session_id for update; if not found then raise exception 'Session not found'; end if; if result.status<>'active' then raise exception 'This session is not active'; end if; update public.parking_sessions set status='completed',exit_time=now() where id=p_session_id returning * into result; update public.parking_slots set status='available' where id=result.slot_id; return result; end; $$;
grant execute on function public.create_parking_session(uuid,text),public.approve_parking_entry(uuid),public.complete_parking_exit(uuid) to authenticated;
insert into public.parking_slots(slot_number,vehicle_type) values ('B01','bike'),('B02','bike'),('B03','bike'),('B04','bike'),('B05','bike'),('B06','bike'),('B07','bike'),('B08','bike'),('B09','bike'),('B10','bike'),('C01','car'),('C02','car'),('C03','car'),('C04','car'),('C05','car'),('C06','car'),('C07','car'),('C08','car'),('C09','car'),('C10','car') on conflict (slot_number) do nothing;
